var CHAVES = { rascunho: "patas:rascunho-cadastro", filtro: "patas:filtro-animais" };
function gravar(chave, valor) {
try { localStorage.setItem(chave, JSON.stringify(valor)); } catch (e) {  }
}
function ler(chave, padrao) {
try {
var texto = localStorage.getItem(chave);
return texto === null ? padrao : JSON.parse(texto);
} catch (e) { return padrao; }
}
function apagar(chave) {
try { localStorage.removeItem(chave); } catch (e) {  }
}
(function () {
function salvarRascunho(form) {
var dados = {};
form.querySelectorAll("input, select, textarea").forEach(function (c) {
if (!c.name || c.type === "checkbox") return;
if (c.type === "radio") { if (c.checked) dados[c.name] = c.value; return; }
dados[c.name] = c.value;
});
gravar(CHAVES.rascunho, dados);
}
function restaurarRascunho() {
var form = document.querySelector(".formulario");
if (!form) return;
var dados = ler(CHAVES.rascunho, null);
if (!dados || typeof dados !== "object" || !Object.keys(dados).length) return;
Object.keys(dados).forEach(function (nome) {
var campos = form.querySelectorAll('[name="' + nome + '"]');
campos.forEach(function (c) {
if (c.type === "radio") c.checked = c.value === dados[nome];
else c.value = dados[nome];
});
});
if (window.mostrarToast) mostrarToast("Rascunho restaurado", "info");
}
document.addEventListener("input", function (e) {
var form = e.target.closest && e.target.closest(".formulario");
if (form) salvarRascunho(form);
});
document.addEventListener("DOMContentLoaded", restaurarRascunho);
document.addEventListener("spa:pagina", restaurarRascunho);
})();;
(function () {
function formatar(d) { return d.toISOString().slice(0, 10); }
function anos(nascimento, hoje) {
var a = hoje.getFullYear() - nascimento.getFullYear();
var m = hoje.getMonth() - nascimento.getMonth();
if (m < 0 || (m === 0 && hoje.getDate() < nascimento.getDate())) a--;
return a;
}
function iniciarDatas() {
var campo = document.getElementById("nascimento");
if (!campo || campo.dataset.datas) return;
campo.dataset.datas = "true";
var hoje = new Date();
var max = new Date(hoje.getFullYear() - 18, hoje.getMonth(), hoje.getDate());
var min = new Date(hoje.getFullYear() - 100, hoje.getMonth(), hoje.getDate());
campo.max = formatar(max);
campo.min = formatar(min);
campo.addEventListener("input", function () {
var info = document.getElementById("idade-info");
if (!info || !campo.value) { if (info) info.textContent = ""; return; }
info.textContent = "Idade: " + anos(new Date(campo.value + "T00:00:00"), new Date()) + " anos";
});
}
document.addEventListener("DOMContentLoaded", iniciarDatas);
document.addEventListener("spa:pagina", iniciarDatas);
})();;
function mostrarToast(mensagem, tipo) {
var area = document.getElementById("toasts");
if (!area) return;
var toast = document.createElement("div");
toast.className = "toast toast-" + (tipo || "info");
var texto = document.createElement("span");
texto.textContent = mensagem;
var fechar = document.createElement("button");
fechar.type = "button";
fechar.setAttribute("aria-label", "Fechar notificação");
fechar.textContent = "×";
toast.append(texto, fechar);
area.append(toast);
var tempo;
function agendar() { tempo = setTimeout(remover, 5000); }
function remover() { clearTimeout(tempo); toast.remove(); }
fechar.addEventListener("click", remover);
toast.addEventListener("mouseenter", function () { clearTimeout(tempo); });
toast.addEventListener("focusin", function () { clearTimeout(tempo); });
toast.addEventListener("mouseleave", agendar);
toast.addEventListener("focusout", agendar);
agendar();
}
(function () {
document.addEventListener("click", function (e) {
var abrir = e.target.closest("[data-abrir-modal]");
if (abrir) { var m = document.getElementById(abrir.dataset.abrirModal); if (m && m.showModal) m.showModal(); return; }
if (e.target.closest("[data-fechar-modal]")) { var d = e.target.closest("dialog"); if (d) d.close(); return; }
var alerta = e.target.closest("[data-fechar-alerta]");
if (alerta) { var a = alerta.closest(".alerta"); if (a) a.remove(); return; }
var t = e.target.closest("[data-toast]");
if (t) mostrarToast(t.dataset.mensagem || "Pronto!", t.dataset.toast);
});
})();;
function mascaras(id, valor) {
var n = valor.replace(/\D/g, "");
if (id === "cpf") {
n = n.slice(0, 11);
return n.replace(/^(\d{3})(\d)/, "$1.$2").replace(/^(\d{3})\.(\d{3})(\d)/, "$1.$2.$3").replace(/\.(\d{3})(\d)/, ".$1-$2");
}
if (id === "telefone") {
n = n.slice(0, 11);
if (n.length > 10) return n.replace(/^(\d{2})(\d{5})(\d{0,4})/, "($1) $2-$3");
return n.replace(/^(\d{2})(\d{0,4})(\d{0,4})/, function (_, a, b, c) { return "(" + a + ")" + (b ? " " + b : "") + (c ? "-" + c : ""); });
}
if (id === "cep") {
n = n.slice(0, 8);
return n.replace(/^(\d{5})(\d)/, "$1-$2");
}
return valor;
}
document.addEventListener("input", function (e) {
var id = e.target.id;
if (id === "cpf" || id === "telefone" || id === "cep") e.target.value = mascaras(id, e.target.value);
});;
var ANIMAIS = [
{ nome: "Thor", genero: "m", especie: "cachorro", imagem: "animal-thor", alt: "Ilustração do cachorro Thor, de pelo caramelo", descricao: "Cachorro, 2 anos, castrado. Brincalhão e ótimo com crianças.", etiquetas: [{ texto: "Vacinado", variante: "sucesso" }, { texto: "Castrado", variante: "info" }] },
{ nome: "Luna", genero: "f", especie: "gato", imagem: "animal-luna", alt: "Ilustração da gata Luna, de pelo escuro e olhos verdes", descricao: "Gata, 1 ano, castrada. Calma e carinhosa, ideal para apartamento.", etiquetas: [{ texto: "Vacinada", variante: "sucesso" }] },
{ nome: "Pipoca", genero: "f", especie: "cachorro", imagem: "animal-pipoca", alt: "Ilustração da cachorra Pipoca, de pelo branco", descricao: "Cachorra, 4 meses, porte pequeno. Cheia de energia e vacinada.", etiquetas: [{ texto: "Filhote", variante: "alerta" }, { texto: "Vacinada", variante: "sucesso" }] }
];;
(function () {
function criarEtiqueta(et) {
var li = document.getElementById("modelo-etiqueta").content.cloneNode(true).querySelector("li");
li.textContent = et.texto;
li.classList.add("variante-" + et.variante);
return li;
}
function criarCartao(animal) {
var frag = document.getElementById("modelo-cartao-animal").content.cloneNode(true);
var fem = animal.genero === "f";
frag.querySelector("h3").textContent = animal.nome;
frag.querySelector("p").textContent = animal.descricao;
var img = frag.querySelector("img");
img.src = "../img/" + animal.imagem + ".jpg";
img.alt = animal.alt;
frag.querySelector("source").srcset = "../img/" + animal.imagem + ".webp";
var lista = frag.querySelector("ul");
lista.setAttribute("aria-label", "Características de " + animal.nome);
lista.append.apply(lista, animal.etiquetas.map(criarEtiqueta));
frag.querySelector("a").textContent = "Quero adotar " + (fem ? "a " : "o ") + animal.nome;
return frag;
}
function renderizarAnimais(filtro) {
var alvo = document.getElementById("grade-animais");
if (!alvo) return;
var visiveis = ANIMAIS.filter(function (a) { return filtro === "todos" || a.especie === filtro; });
alvo.replaceChildren.apply(alvo, visiveis.map(criarCartao));
var c = document.getElementById("contagem");
if (c) c.textContent = visiveis.length + " animal(is) exibido(s)";
document.querySelectorAll("[data-filtro]").forEach(function (b) {
b.setAttribute("aria-pressed", String(b.dataset.filtro === filtro));
});
gravar(CHAVES.filtro, filtro);
}
function iniciar() {
if (!document.getElementById("grade-animais")) return;
var salvo = ler(CHAVES.filtro, "todos");
var valido = document.querySelector('[data-filtro="' + salvo + '"]');
renderizarAnimais(valido ? salvo : "todos");
}
document.addEventListener("click", function (e) {
var b = e.target.closest("[data-filtro]");
if (b) renderizarAnimais(b.dataset.filtro);
});
document.addEventListener("DOMContentLoaded", iniciar);
document.addEventListener("spa:pagina", iniciar);
})();;
function iniciarFormulario() {
var form = document.querySelector(".formulario");
if (!form || form.dataset.pronto) return;
form.dataset.pronto = "true";
var envio = document.getElementById("envio");
var termos = document.getElementById("termos");
var avisouErro = false;
termos.addEventListener("change", function () { envio.disabled = !termos.checked; });
form.addEventListener("invalid", function () {
if (avisouErro) return;
avisouErro = true;
if (window.mostrarToast) mostrarToast("Revise os campos destacados em vermelho", "erro");
setTimeout(function () { avisouErro = false; }, 0);
}, true);
form.addEventListener("submit", function (e) {
e.preventDefault();
var nome = document.getElementById("nome").value.trim().split(" ")[0];
document.getElementById("nome-sucesso").textContent = nome;
document.getElementById("modal-sucesso").showModal();
if (window.mostrarToast) mostrarToast("Cadastro enviado!", "sucesso");
form.reset();
envio.disabled = true;
apagar(CHAVES.rascunho);
});
}
document.addEventListener("DOMContentLoaded", iniciarFormulario);
document.addEventListener("spa:pagina", iniciarFormulario);;
(function () {
if (location.protocol === "file:") return;
var app = document.getElementById("app");
var cache = new Map();
function buscar(url) {
if (cache.has(url)) return Promise.resolve(cache.get(url));
return fetch(url).then(function (r) {
if (!r.ok) throw new Error(r.status);
return r.text();
}).then(function (html) {
var doc = new DOMParser().parseFromString(html, "text/html");
var main = doc.getElementById("app");
var pagina = { nos: Array.from(main.childNodes), classe: main.className, titulo: doc.title };
cache.set(url, pagina);
return pagina;
});
}
function renderizar(pagina, url) {
var fragmento = document.createDocumentFragment();
pagina.nos.forEach(function (no) { fragmento.appendChild(document.importNode(no, true)); });
app.replaceChildren(fragmento);
app.className = pagina.classe;
document.title = pagina.titulo;
var atual = new URL(url, location.href).pathname.split("/").pop();
document.querySelectorAll(".menu a").forEach(function (a) {
var dest = a.getAttribute("href").split("#")[0];
if (dest === atual) a.setAttribute("aria-current", "page"); else a.removeAttribute("aria-current");
});
var h1 = app.querySelector("h1");
if (h1) { h1.setAttribute("tabindex", "-1"); h1.focus(); }
document.dispatchEvent(new CustomEvent("spa:pagina"));
}
function navegar(url, empilhar) {
app.setAttribute("aria-busy", "true");
buscar(url).then(function (pagina) {
if (empilhar) history.pushState({}, "", url);
renderizar(pagina, url);
}).catch(function () { location.href = url; })
.finally(function () { app.removeAttribute("aria-busy"); });
}
document.addEventListener("click", function (e) {
if (e.ctrlKey || e.metaKey || e.shiftKey || e.button !== 0) return;
var a = e.target.closest("a[href]");
if (!a || a.target) return;
var href = a.getAttribute("href");
if (!/\.html$/.test(href.split("#")[0]) || href.charAt(0) === "#") return;
if (href.indexOf("#") > -1) return;
e.preventDefault();
navegar(a.href, true);
});
window.addEventListener("popstate", function () { navegar(location.href, false); });
})();;
(function () {
var botao = document.querySelector(".menu-botao");
var nav = document.getElementById("menu-nav");
if (!botao || !nav) return;
function definir(aberto) {
nav.classList.toggle("aberto", aberto);
botao.setAttribute("aria-expanded", String(aberto));
botao.setAttribute("aria-label", aberto ? "Fechar menu" : "Abrir menu");
}
botao.addEventListener("click", function () { definir(!nav.classList.contains("aberto")); });
nav.addEventListener("click", function (e) { if (e.target.closest("a")) definir(false); });
document.addEventListener("keydown", function (e) {
if (e.key === "Escape" && nav.classList.contains("aberto")) { definir(false); botao.focus(); }
});
window.matchMedia("(min-width: 768px)").addEventListener("change", function () { definir(false); });
})();
